const FOLDERS: Record<string, string> = {"src":"folder-src",".src":"folder-src","_src":"folder-src","-src":"folder-src","__src__":"folder-src","srcs":"folder-src",".srcs":"folder-src","_srcs":"folder-src","-srcs":"folder-src","__srcs__":"folder-src","source":"folder-src",".source":"folder-src","_source":"folder-src","-source":"folder-src","__source__":"folder-src","sources":"folder-src",".sources":"folder-src","_sources":"folder-src","-sources":"folder-src","__sources__":"folder-src","code":"folder-src",".code":"folder-src","_code":"folder-src","-code":"folder-src","__code__":"folder-src","test":"folder-test",".test":"folder-test","_test":"folder-test","-test":"folder-test","__test__":"folder-test","tests":"folder-test",".tests":"folder-test","_tests":"folder-test","-tests":"folder-test","__tests__":"folder-test","testing":"folder-test",".testing":"folder-test","_testing":"folder-test","-testing":"folder-test","__testing__":"folder-test","snapshots":"folder-test",".snapshots":"folder-test","_snapshots":"folder-test","-snapshots":"folder-test","__snapshots__":"folder-test","spec":"folder-test",".spec":"folder-test","_spec":"folder-test","-spec":"folder-test","__spec__":"folder-test","specs":"folder-test",".specs":"folder-test","_specs":"folder-test","-specs":"folder-test","__specs__":"folder-test","testfiles":"folder-test",".testfiles":"folder-test","_testfiles":"folder-test","-testfiles":"folder-test","__testfiles__":"folder-test"};
// lgtm's own additions. ProGuard / R8 rules (the theme has no icon for them; it reads .pro as Prolog): Android's.
Object.assign(EXT, { pro: 'android' });
// Gradle's source sets (module trees leave out their src/): main is the source, and Android's other test ones.
Object.assign(FOLDERS, { main: 'folder-src', androidtest: 'folder-test', testfixtures: 'folder-test', integrationtest: 'folder-test' });
Object.assign(NAMES, { 'proguard-rules.txt': 'android', 'proguard-android.txt': 'android', 'proguard.cfg': 'android' });

// As VS Code picks: the whole file name first, then the longest extension (foo.test.ts → test.ts before ts).
const uris = new Map<string, string>();
export function fileIcon(path: string): string {
  const name = path.split('/').pop()!.toLowerCase();
  let icon = NAMES[name];
  const parts = name.split('.');
  for (let k = 1; !icon && k < parts.length; k++) icon = EXT[parts.slice(k).join('.')];
  icon ??= 'file';
  if (!uris.has(icon)) uris.set(icon, `data:image/svg+xml,${encodeURIComponent(SVG[icon])}`);
  return uris.get(icon)!;
}

// `name` may be a chain ("src/test/java"): a test folder in it wins, then any the theme knows.
export function folderIcon(name: string, open: boolean): string {
  const kinds = name.toLowerCase().split('/').map((n) => FOLDERS[n]);
  const icon = (kinds.find((k) => k === 'folder-test') ?? kinds.findLast(Boolean) ?? 'folder') + (open ? '-open' : '');
  if (!uris.has(icon)) uris.set(icon, `data:image/svg+xml,${encodeURIComponent(FOLDER_SVG[icon])}`);
  return uris.get(icon)!;
}
